# scratch_slow: builds the VU0 half of the skinning fast path (oracle src/skinff_vu.rs) from the native prog0 translation
# (src/vu0_prog0.rs, @generated by vu0gen.py): follows the node chain of one resume (start node -> the next park) and
# emits that chain as straight-line code with the same statements.
# Changes to the statements: coverage counters dropped, the pair count summed into a constant, the cycle count dropped
# (vu0_exec's result is unused on the CTC2 path), and the MAC / status flag blocks reduced to "remember the last result":
# the fast path runs only while the sticky status bits (vi16 bits 6, 7) are already set, so OR-ing more zero / sign
# lanes into them changes nothing, and only the last result's lanes reach the MAC flag and the status Z / S bits.
# [PC] prog0 holds four copies of the per-vertex code, one per vertex group (counters vi03, vi04, vi05, then the
# drain copy counted by vi11), each with a vi02 wait and a vi01 wait. One function per wait (park): the group counter's
# test is a real branch (the steady tail parks in the same copy, the taken tail runs into the next copy and parks there);
# every other branch outcome the straight-line code assumes is tested at run time (`chk`), and a path that ends the
# program (E bit) returns chk = false: the caller then marks the pass bad and the compiled code runs it.
# usage: python skinff_gen.py SRC/vu0_prog0.rs OUT.rs
import re, sys
src = open(sys.argv[1], encoding='utf-8').read().split('\n')
nodes = {}
i = 0
while i < len(src):
    m = re.match(r'^ {16}(\d+) => \{$', src[i])
    if m:
        n = int(m.group(1)); j = i + 1; body = []
        while not re.match(r'^ {16}\}$', src[j]):
            body.append(src[j][20:] if src[j].startswith(' ' * 20) else src[j].strip())
            j += 1
        nodes[n] = body
        i = j
    i += 1
entry = {}
k = src.index('pub fn entry_node(pc: usize) -> Option<u32> {')
while src[k].strip() != '}':
    m = re.match(r'^\s+0x([0-9a-f]+) => Some\((\d+)\),$', src[k])
    if m:
        entry[int(m.group(1), 16)] = int(m.group(2))
    k += 1

FLAG = re.compile(r'^\{ let \(z, s\) = zs_masks\(u, (\d+)\); zl = z; sl = s; zo \|= z; so \|= s; fl_any = true; \}$')
# The waits (park pc -> the VI register they test) and the group counters (a branch on one of them is a real branch).
WAITS = {0x1c8: 2, 0x0f0: 1, 0x418: 2, 0x2f0: 1, 0x6a8: 2, 0x560: 1, 0x858: 2, 0x780: 1}
COUNTERS = (3, 4, 5, 11)

def cond_reg(n):
    for l in nodes[n]:
        if l.strip().startswith('let c = (vi[0] as u16 as i16) == (vi['):
            return int(re.findall(r'vi\[(\d+)\]', l)[-1])
    return None

def chain(n, start, depth=0):
    """Statements from node `n` to a park (or the E bit). The start node's wait branch is taken (the resume), a counter
    branch splits into both tails, every other branch is assumed not taken (tested at run time)."""
    out = []; pairs = 0; seen = []
    while True:
        seen.append(n)
        assert len(seen) < 400, seen
        body = nodes[n]
        k = 0
        nxt = None
        while k < len(body):
            l = body[k].strip()
            if l.startswith('if COV') or l.startswith('cyc +='):
                k += 1; continue
            if l == 'pairs += 1;':
                pairs += 1; k += 1; continue
            m = FLAG.match(l)
            if m:
                out.append(f'fu = u; fm = {m.group(1)};'); k += 1; continue
            m = re.match(r'^n = (\d+); continue;$', l)
            if m:
                nxt = int(m.group(1)); break
            if l == 'if tk {':
                blk = []
                k += 1
                while body[k].strip() != '} else {':
                    blk.append(body[k].strip()); k += 1
                a = int(re.search(r'n = (\d+);', blk[-1]).group(1))
                b = int(re.search(r'n = (\d+);', body[k + 1]).group(1))
                assert body[k + 2].strip() == '}' and body[k + 3].strip() == 'continue;', body[k:k + 4]
                if n == start and depth == 0 and len(seen) == 1:
                    out.append(f'chk &= tk; // node {n} (the resumed wait is left)')
                    nxt = a
                elif cond_reg(n) in COUNTERS:
                    assert depth < 4, seen
                    ta, pa = chain(a, start, depth + 1)
                    tb, pb = chain(b, start, depth + 1)
                    out.append(f'if tk {{ // node {n}: vi{cond_reg(n):02} = 0')
                    out += ['    ' + x for x in ta]
                    out.append(f'    pairs += {pa};')
                    out.append('} else {')
                    out += ['    ' + x for x in tb]
                    out.append(f'    pairs += {pb};')
                    out.append('}')
                    return out, pairs
                else:
                    out.append(f'chk &= !tk; // node {n}')
                    nxt = b
                break
            m = re.match(r"^break 'run \((\d+)usize, (true|false)\);$", l)
            if m:
                if m.group(2) == 'true':
                    pc = int(m.group(1))
                    assert pc in WAITS, hex(pc)
                    out.append(f'park = {pc:#x};')
                else:
                    out.append('chk = false; // the program ends (E bit)')
                    out.append('park = 0;')
                return out, pairs
            if 'break' in l or 'return' in l or 'continue' in l:
                raise SystemExit(f'node {n}: unexpected control statement {l!r}')
            out.append(l)
            k += 1
        if nxt is None:
            raise SystemExit(f'node {n}: no successor')
        n = nxt

o = ['//! @generated by tools/skinff_gen.py from src/vu0_prog0.rs. Do not edit.',
     '//! The prog0 resumes of the one-joint vertex loop as straight-line code (see skinff.rs): one function per wait of the',
     '//! four vertex-group copies; a group counter at 0 runs into the next copy.',
     '#![allow(unused_mut, unused_assignments, unused_variables, unused_unsafe, clippy::all)]',
     'use crate::vu0aot::*;', 'use std::arch::x86_64::{_mm_cvtsi128_si32, _mm_shuffle_epi32};', '',
     '/// Lane L of a vector register as the scalar (MTIR / RSQRT operand reads).', '#[inline(always)]',
     'fn ext<const L: i32>(v: V) -> u32 { unsafe { _mm_cvtsi128_si32(_mm_shuffle_epi32::<L>(v)) as u32 } }', '',
     '/// A resume\'s outcome: the last flag-setting result and its lane mask, the wait it parked at, the instruction pairs',
     '/// it ran, and whether every assumed branch outcome held (false: the pass must be redone by the compiled code).',
     'pub struct Res {', '    pub fu: V,', '    pub fm: u32,', '    pub park: usize,', '    pub pairs: u64,', '    pub ok: bool,', '}', '']
VR = r'(?<![A-Za-z_0-9])v(\d+)(?![A-Za-z0-9_])'
def localize(body):
    """vf register file in host vector locals (v0..v31): every register the code touches is loaded at the start and the
    written ones stored at the end (both tails of a counter branch see defined values). Nothing else touches vf in between,
    so the values are the same as when every access went through memory."""
    out = []; used = set(); wrote = set()
    for l in body:
        l2 = re.sub(r'\*vf\.add\((\d+)\)', lambda m: f'ext::<{int(m.group(1)) % 4}>(v{int(m.group(1)) // 4})', l)
        l2 = re.sub(r'ldv\(vf\.add\((\d+)\)\)', lambda m: f'v{int(m.group(1)) // 4}', l2)
        m = re.match(r'^(\s*)stv\(vf\.add\((\d+)\), (.*)\);$', l2)
        if m:
            k = int(m.group(2)); assert k % 4 == 0
            wrote.add(k // 4); used.add(k // 4)
            l2 = f'{m.group(1)}v{k // 4} = {m.group(3)};'
        else:
            assert 'vf.add' not in l2, l2
        for v in re.findall(VR, l2): used.add(int(v))
        out.append(l2)
    return out, sorted(used), sorted(wrote)

names = []
for park in sorted(WAITS):
    start = entry[park]
    body, pairs = chain(start, start)
    body, used, wrote = localize(body)
    nm = f'res_{park:03x}'
    names.append((park, nm))
    print(f'{nm}: start node {start}, {len(body)} statements', file=sys.stderr)
    o.append(f'/// Resume at the wait {park:#05x} (vi{WAITS[park]:02}).')
    o.append('#[inline(always)]')
    o.append(f'pub unsafe fn {nm}(w: &mut [V; 32], dm: *mut u8, vi: &mut [u32; 32], acc: &mut V) -> Res {{')
    for k in used:
        o.append(f'    let mut v{k}: V = w[{k}];')
    o += ['    let mut qp: u32 = 0;', '    let mut tk = false;', '    let mut chk = true;', '    let mut park: usize = 0;',
          f'    let mut pairs: u64 = {pairs};', '    let mut fu: V = std::mem::zeroed();', '    let mut fm: u32 = 0;', '    let mut acc_ = *acc;']
    for l in body:
        o.append('    ' + re.sub(r'(?<![A-Za-z_])acc(?![A-Za-z_])', 'acc_', l))
    for k in wrote:
        o.append(f'    w[{k}] = v{k};')
    o.append('    *acc = acc_;')
    o.append('    Res { fu, fm, park, pairs, ok: chk }')
    o.append('}')
    o.append('')
o.append('/// The resume of the wait VU0 is parked at (`park`), kicked through vi`n` (a CTC2 to the register the wait tests).')
o.append('#[inline(always)]')
o.append('pub unsafe fn resume(park: usize, n: usize, w: &mut [V; 32], dm: *mut u8, vi: &mut [u32; 32], acc: &mut V) -> Res {')
o.append('    match (park, n) {')
for park, nm in names:
    o.append(f'        ({park:#05x}, {WAITS[park]}) => {nm}(w, dm, vi, acc),')
o.append('        _ => Res { fu: std::mem::zeroed(), fm: 0, park, pairs: 0, ok: false },')
o.append('    }')
o.append('}')
o.append('')
o.append('/// The vi02 waits (where the loop head finds VU0 parked).')
o.append('pub const VI02_WAITS: [usize; 4] = [' + ', '.join(f'{p:#05x}' for p in sorted(WAITS) if WAITS[p] == 2) + '];')
open(sys.argv[2], 'w', encoding='utf-8', newline='\n').write('\n'.join(o) + '\n')
